"""Seal all owned evidence and measured counts, with prior-file preservation."""
import importlib.util,json,subprocess,yaml
from pathlib import Path
B=Path(__file__).resolve().parents[1];sp=importlib.util.spec_from_file_location('stages',B/'target_stages.py');s=importlib.util.module_from_spec(sp);sp.loader.exec_module(s)
selection=json.loads((B/'selection.json').read_bytes());integration=json.loads((B/'review/final_integration/result.json').read_bytes());paths=set();table=[]
counts={'runs':0,'exact_records':0,'rejected_P4_mutations':0,'reviewed_generators':0,'reviewed_relations':0,'reviewed_compositions':0,'retained_failed_checkpoints':0,'external_provider_calls':0,'chat_cost':'unmeasured'}
for row in selection['nodes']:
    run=s.ROOT/row['run'];review=run.parent.parent/'reviews/20261019_resources_audit';acc=json.loads((run/'accepted.json').read_bytes());prof=json.loads((run/'p0/profile.json').read_bytes());candidate=json.loads((run/acc['attempt']/'candidate.json').read_bytes());delta=yaml.safe_load((review/'operad_delta.yaml').read_bytes());mutants=json.loads((run/'p4/host_check.json').read_bytes())['predicate_results']['mutants']
    counts['runs']+=1;counts['exact_records']+=len(candidate['data']['records']);counts['rejected_P4_mutations']+=len(mutants);counts['retained_failed_checkpoints']+=len(acc['failed_checkpoints'])
    for key,field in [('reviewed_generators','add_or_refine_generators'),('reviewed_relations','add_or_refine_relations'),('reviewed_compositions','checked_compositions')]:counts[key]+=len(delta[field])
    s.save(review/'review_result.json',{'task_id':row['node_id'],'status':'scoped_result_or_obstruction_reviewed','accepted':acc,'integration':integration,'claim_boundary':prof['claim_boundary'],'rejected_P4_mutations':len(mutants),'authority_effect':'None'})
    path=s.ROOT/row['operad_collection'];collection=yaml.safe_load(path.read_bytes());collection['latest_review']['status']='reviewed_with_targeted_native_integration';path.write_bytes(yaml.safe_dump(collection,sort_keys=False,allow_unicode=True,width=100).encode());paths.add(path)
    for folder in (run,review):paths.update(p for p in folder.rglob('*') if p.is_file() and '__pycache__' not in p.parts)
    paths.add(run.parent.parent/'.gitattributes')
    for pin in candidate['source_pins']:paths.add(s.ROOT/pin['path'].split('/'+acc['attempt']+'/construction/',1)[1])
    table.append('| '+row['node_id']+' | '+prof['claim_boundary']['supports'].replace('|','/')+' | '+prof['claim_boundary']['does_not_support'].replace('|','/')+' |')
# Verify all pre-existing results, prompts and unrelated operad collections against Git blobs.
base=selection['base_commit'];selected={r['operad_collection'] for r in selection['nodes']};tracked=subprocess.check_output(['git','ls-tree','-rz',base,'--','dag/results','dag/prompts','dag/pfp/prompt_audit.json','dag/pfp/filename_custody.json','dag/operads'],cwd=s.ROOT).split(b'\0');preserved=[];old_files=[]
for line in tracked:
    if not line:continue
    meta,raw=line.split(b'\t',1);name=raw.decode();oid=meta.split()[-1].decode()
    if name=='dag/operads/index.json' or name in selected:continue
    old_files.append((name,oid))
actuals=subprocess.check_output(['git','hash-object','--no-filters','--stdin-paths'],input='\n'.join(n for n,_ in old_files)+'\n',cwd=s.ROOT,text=True).splitlines()
if len(actuals)!=len(old_files):raise ValueError('Preservation file coverage')
for (name,oid),actual in zip(old_files,actuals):
    p=s.ROOT/name
    if actual!=oid:raise ValueError('Prior artifact changed '+name)
    preserved.append({'path':name,'git_blob':oid,'sha256':s.sha(p)})
s.save(B/'review/preservation.json',{'base_commit':base,'files':preserved,'count':len(preserved),'scope':'Every tracked old result, prompt, audit/filename ledger and nonselected operad collection; selected historical target metadata separately verified by replay.'})
s.save(B/'summary.json',{'batch_id':selection['batch_id'],'status':'all_twenty_scoped_steps_reviewed','counts':counts,'integration':integration,'preserved_prior_files':len(preserved),'remaining_unrun_prompts':sum(not n.get('latest_run') for n in json.loads((s.ROOT/'dag/operads/index.json').read_bytes())['nodes']),'scope':'Twenty local staged scoped results/obstructions; no blanket original-target, physical, full-operad-coherence or authority promotion.'})
readme='# PFP prompts 52 through 71\n\nTwenty previously unrun prompts executed locally through P0/P1/P2/P4/P5, with P3 only for a real failed Lean compilation. Every checkpoint retains its operad delta, input/source bindings and actual checker/native results. No external provider dispatch; active chat cost is unmeasured. One local Codex researcher performed the review.\n\n'+json.dumps(counts,sort_keys=True)+'\n\n'+json.dumps(integration,sort_keys=True)+'\n\nThe first Lean gate failed on missing explicit Mathlib imports and an absolute-value token spacing issue. Its diagnostics and recovery-generated sorryAx reports remain rejected; P3 preserves the exact numerical certificate and a fresh compiler run passes all named axiom checks. No intentional failures were manufactured.\n\nSource review fences definitional UsefulQC/S aliases, unbounded multiples mislabeled as torsion exclusion, source provider PASS annotations, route-index arithmetic, unnormalized channel mixing and toy authority gates. New exact controls use actual Gaussian amplitudes, joint/contextual tables, product density matrices, stochastic kernels and normalized rational Kraus matrices. Universal Lean results include rational population non-descent, finite convex separator soundness and all-finite rational stochastic contraction; concrete array-to-formal and physical transports remain explicit. Full refined-carrier operad identities, substitution, symmetry and coherence are open where listed.\n\nHistorical expected paper hashes remain unchanged. Captured current paper bytes resolve through the explicit filename-custody ledger from PR82, with ledger digest and source snapshots retained. Every prior tracked result/prompt and unrelated collection remains byte-identical to the selected base; see review/preservation.json. Counts are unique tests/theorems, not sums of repeated stage gates. Cached pinned Mathlib is imported; full Mathlib/transitive dependency/whole-repository/hosted CI is not claimed.\n\n| Prompt | Supported step | Remaining obligation |\n|---|---|---|\n'+'\n'.join(table)+'\n\nRead-only replay and custody guards:\n\n    py -3.9 -X utf8 verify_batch.py\n    py -3.9 -X utf8 -O verify_batch.py\n    py -3.9 -X utf8 test_custody_guards.py -v\n\nGitHub commit/PR/merge state must be independently verified. AuthorityEffect: None.\n'
(B/'README.md').write_bytes(readme.encode());paths.add(s.ROOT/'dag/operads/index.json');paths.update(p for p in B.rglob('*') if p.is_file() and '__pycache__' not in p.parts)
s.save(B/'manifest.json',{'scope':'All owned batch/run/review artifacts and exact construction/build/collection source bytes, excluding this manifest itself. Prior historical files have a separate Git-blob preservation receipt.','files':[s.pin(p) for p in sorted(paths)]})
print(json.dumps({'counts':counts,'preserved_prior_files':len(preserved)}),flush=True)
